solution:
function NumDecodings(s: string) -> int {
  let chars = s.chars();
  let n = chars.length();
  if (n == 0) {
    return 0;
  }
  if (chars[0] == "0") {
    return 0;
  }
  let prev2 = 1;
  let prev1 = 1;
  let i = 1;
  while (i < n) {
    let cur = 0;
    if (chars[i] != "0") {
      cur += prev1;
    }
    let twoStr = chars[i - 1] + chars[i];
    let two = int.parse(twoStr);
    if (two >= 10 && two <= 26) {
      cur += prev2;
    }
    prev2 = prev1;
    prev1 = cur;
    i += 1;
  }
  return prev1;
}
